INSERT INTO states (id, phase, kind, description) VALUES
  ('request_received', 'entry', 'active', 'Authenticated request received; cycle created (creation or evolution)'),
  ('overlap_search', 'entry', 'active', 'Agent task: does a tool of the registry already cover the need? (creation only)'),
  ('gate_overlap', 'entry', 'gate', 'The admin decides on a plausible overlap, a technical failure or an unreadable report'),
  ('repo_creation', 'entry', 'active', 'Creation of the repository from the template, idempotent (does nothing if the repository exists)'),
  ('scoping', 'scoping', 'active', 'Budget check, then the scoping agent task (mock-up + specification)'),
  ('gate_scoping_budget', 'scoping', 'gate', 'Cycle budget (scoping) reached: the admin continues (top-up), clarifies or refuses'),
  ('gate_scoping_blocked', 'scoping', 'gate', 'Repeated technical failures, attempts cap or duration: the admin decides'),
  ('mockup_deployment', 'scoping', 'active', 'W4: deployment of the mock-up on <tool>.scoping.<domain>, wait for availability + health'),
  ('waiting_scoping_feedback', 'scoping', 'waiting', 'The requester looks at the mock-up and answers in the chat (reminders at 24/48/72 h)'),
  ('scoping_pause', 'scoping', 'waiting', 'Requester silent for 96 h (3 reminders): mock-up stopped, admin told; their free message resumes the cycle as a correction request; 30 days without an answer → abandonment and archiving'),
  ('contract', 'contract', 'active', 'Agent task: OpenAPI + Gherkin scenarios from the validated scope'),
  ('gate_contract_blocked', 'contract', 'gate', 'Contract failed technically or hardening budget (same envelope) reached: the admin decides'),
  ('hardening_execution', 'hardening', 'active', 'Guard-rail checks (budget, then stagnation / cap / duration), then the tests task, then the builder task (only the roles concerned, ADR-021)'),
  ('hardening_integration', 'hardening', 'active', 'Merge of the role branches onto the iteration branch; a conflict becomes a deviation for the file''s owner role'),
  ('hardening_review', 'hardening', 'active', 'Fan-out of the security review / quality review, read-only'),
  ('hardening_evaluation', 'hardening', 'active', 'Evaluation of the round: compliance (fail-closed, deviations from the agents, the CI and the Preview pipeline, tree digest per role), stagnation (cascade rule+file / category+file / previous_id, patience, oscillation — D20), cap, duration, budget'),
  ('gate_hardening_blocked', 'hardening', 'gate', 'Escalation (stagnation — precise reason: fine fingerprint, same category in the file, inherited deviation, no progress, oscillation —, cap, duration, budget): the admin sees which check fails, its result and for how many rounds (pipeline_results, deviations, tasks.report); continue (top-up), clarify or refuse'),
  ('merge', 'delivery', 'active', 'Diff check per role (out of scope = round deviation, back to hardening), then squash into main by the orchestrator account'),
  ('waiting_ci', 'delivery', 'waiting', 'The CI builds the image once and publishes its digest'),
  ('candidate_image', 'delivery', 'active', 'Digest recorded; Gate 1 required only once per tool'),
  ('gate_1', 'delivery', 'gate', 'Gate 1: name and domain of the tool (once per tool, skipped for an evolution); two correction buttons: "correction" or "scope change"'),
  ('preview_deployment', 'delivery', 'active', 'W4: deployment of the digest to Preview'),
  ('preview_pipeline', 'delivery', 'waiting', 'Pipeline 2 against the Preview (perf, accessibility, DAST, acceptance suite), before any feedback from the requester; results recorded against the digest (pipeline_results); red → hardening, green → link sent to the requester'),
  ('waiting_preview_feedback', 'delivery', 'waiting', 'The requester tries a Preview whose checks are green: validated → Gate 2 without running the pipeline again, or two correction buttons: bug or new capability'),
  ('gate_2', 'delivery', 'gate', 'Gate 2: approval of a precise digest, with the results and the dependencies diff'),
  ('prod_deployment', 'delivery', 'active', 'Promotion: W4 deploys the approved digest to Prod; the deployments row (prod) stands for the release, no dedicated table'),
  ('gate_delivery_blocked', 'delivery', 'gate', 'Technical block after the merge (merge failure, silent CI or pipeline, failed Preview deployment): the admin decides; "retry" starts again from the merge'),
  ('gate_prod_blocked', 'delivery', 'gate', 'Failed Prod deployment: the admin runs again only the Prod deployment of the same approved digest, clarifies or refuses; the last healthy prod deployment stays the reference (D19)'),
  ('gate_incident', 'cross_cutting', 'gate', 'Technical incident (D21): an unexpected internal error interrupted the handling of a state; the admin sees the exact error, retries (back to the original state, taken from the history and checked by the database) or refuses; reminders at 24/48/72 h'),
  ('end_success', 'end', 'end', 'Tool in production: requester notified, cleanup (iteration branches, mock-up containers, scoping subdomain); nothing is deleted in the database'),
  ('end_abandonment', 'end', 'end', 'Abandonment by the requester before the merge, or a 30-day pause without an answer: notified, cleanup; creation → tool archived (never deleted), evolution → the tool in prod goes on'),
  ('end_refusal', 'end', 'end', 'Refusal by the admin at a gate: requester notified, cleanup; creation → tool archived (never deleted), evolution → the tool in prod goes on'),
  ('end_cancellation', 'end', 'end', 'Cancellation by the admin (E15, the only way to stop after the merge): containers stopped, requester notified, cleanup; creation → tool archived (never deleted), evolution → the tool in prod goes on')
INSERT INTO allowed_transitions (from_state, trigger, to_state, note) VALUES
  ('request_received', 'guard:creation', 'overlap_search', 'New tool: overlap search before any scoping'),
  ('request_received', 'guard:evolution', 'scoping', 'Evolution of an existing tool: neither overlap nor repository creation, cycle budget at zero'),
  ('overlap_search', 'guard:not_plausible', 'repo_creation', 'No overlap: the repository is created'),
  ('overlap_search', 'guard:plausible', 'gate_overlap', 'Plausible overlap: the admin decides, with the agent''s reason'),
  ('overlap_search', 'guard:unreadable_report', 'gate_overlap', 'Invalid report: "to be checked", never "not plausible" by default (v1 deviation)'),
  ('overlap_search', 'task:failed', 'gate_overlap', 'Technical failure: the admin decides, to be safe'),
  ('gate_overlap', 'gate:approved', 'repo_creation', 'No redundancy: the repository is created'),
  ('gate_overlap', 'gate:correction', 'repo_creation', 'The admin''s clarification is passed to the first scoping as data'),
  ('gate_overlap', 'gate:refused', 'end_refusal', 'Refusal: end of the cycle, requester notified, cleanup'),
  ('gate_overlap', 'timeout_exceeded', 'gate_overlap', 'Reminder to the admin (24/48/72 h); beyond: "waiting > 72 h" on the dashboard and one reminder a week (notification, no trace) until the decision'),
  ('repo_creation', 'task:done', 'scoping', 'Repository created (or already there on replay): branch protections applied'),
  ('repo_creation', 'task:failed', 'gate_scoping_blocked', 'The forge refuses or does not answer after the retries: "scoping blocked" gate, whose "continue" goes through repo_creation again (idempotent) (decision 3)'),
  ('scoping', 'guard:budget_exceeded', 'gate_scoping_budget', 'Check once per round, before launching it (E2, decision 12): cycle budget reached'),
  ('scoping', 'task:done', 'mockup_deployment', 'Valid report: the mock-up is built by the CI and deployed'),
  ('scoping', 'guard:technical_failure', 'scoping', 'Technical failure: run again with the error in the context; counter of attempts (5 in total, mock-up included) and of repetitions of the same error (D17)'),
  ('scoping', 'guard:escalation', 'gate_scoping_blocked', 'Same error 3 times, 5 attempts in total or work duration exceeded'),
  ('gate_scoping_budget', 'gate:approved', 'scoping', 'Continue: top-up = approved + approvals.budget_top_up_usd (D2, decision 6); without a top-up, the budget check triggers this gate again at once'),
  ('gate_scoping_budget', 'gate:correction', 'scoping', 'The admin''s text becomes the instruction of the next scoping'),
  ('gate_scoping_budget', 'gate:refused', 'end_refusal', 'Refusal: end of the cycle, requester notified, cleanup'),
  ('gate_scoping_budget', 'timeout_exceeded', 'gate_scoping_budget', 'Reminder to the admin (24/48/72 h); beyond: "waiting > 72 h" on the dashboard and one reminder a week (notification, no trace) until the decision'),
  ('gate_scoping_blocked', 'gate:approved', 'repo_creation', 'Continue: counters reset, never the cost; goes through repo_creation again (idempotent, also covers a failed repository creation), then scoping'),
  ('gate_scoping_blocked', 'gate:correction', 'repo_creation', 'The admin''s text becomes the instruction of the next scoping'),
  ('gate_scoping_blocked', 'gate:refused', 'end_refusal', 'Refusal: end of the cycle, requester notified, cleanup'),
  ('gate_scoping_blocked', 'timeout_exceeded', 'gate_scoping_blocked', 'Reminder to the admin (24/48/72 h); beyond: "waiting > 72 h" on the dashboard and one reminder a week (notification, no trace) until the decision'),
  ('mockup_deployment', 'task:done', 'waiting_scoping_feedback', 'Mock-up available (health check OK): link sent to the requester'),
  ('mockup_deployment', 'guard:technical_failure', 'scoping', 'Failed deployment: scoping run again with the error; counts in the 5 attempts and in "same error ×3" (D17; as in v1, where a deployment failure was a scoping failure)'),
  ('mockup_deployment', 'guard:escalation', 'gate_scoping_blocked', 'Same error 3 times, 5 attempts in total or work duration exceeded: the admin decides'),
  ('waiting_scoping_feedback', 'event:scoping_feedback:satisfied', 'contract', 'Scope validated by the requester: the contract is produced'),
  ('waiting_scoping_feedback', 'event:scoping_feedback:correction', 'scoping', 'Not satisfied: new scoping round with the whole chat history (E7)'),
  ('waiting_scoping_feedback', 'event:requester_abandonment', 'end_abandonment', 'The requester abandons from the chat'),
  ('waiting_scoping_feedback', 'timeout_exceeded', 'waiting_scoping_feedback', 'Reminder to the requester at 24, 48, 72 h; no agent run again (decision 13)'),
  ('waiting_scoping_feedback', 'guard:reminders_exhausted', 'scoping_pause', 'Silence 24 h after the 3rd reminder (96 h): pause, mock-up stopped, admin told (D4, decision 13)'),
  ('scoping_pause', 'event:requester_message', 'mockup_deployment', 'The requester''s answer resumes where things stopped: mock-up started again, then their free message is handled as a correction request (scoping run again with that message) (decision 17, D18)'),
  ('scoping_pause', 'event:requester_abandonment', 'end_abandonment', 'The requester abandons from the chat'),
  ('scoping_pause', 'timeout_exceeded', 'end_abandonment', 'Pause without an answer for 30 days: abandonment, requester and admin notified, tool archived — never deleted (decision 1)'),
  ('contract', 'task:done', 'hardening_execution', 'Contract versioned in the repository: parallel work becomes possible'),
  ('contract', 'task:failed', 'gate_contract_blocked', 'Technical failure (or blocked agent, decision 7): dedicated gate so that "continue" runs the contract again and not the scoping or the hardening (decision 4)'),
  ('contract', 'guard:budget_exceeded', 'gate_contract_blocked', 'Budget check once before the launch (E2, decision 12); the contract is counted in the hardening envelope ($20), no threshold of its own (D16)'),
  ('gate_contract_blocked', 'gate:approved', 'contract', 'Continue (top-up = approved + amount; without a top-up when the budget is what blocks, the gate triggers again): the contract is run again'),
  ('gate_contract_blocked', 'gate:correction', 'contract', 'The admin''s text becomes the instruction of the contract'),
  ('gate_contract_blocked', 'gate:refused', 'end_refusal', 'Refusal: end of the cycle, requester notified, cleanup'),
  ('gate_contract_blocked', 'timeout_exceeded', 'gate_contract_blocked', 'Reminder to the admin (24/48/72 h); beyond: "waiting > 72 h" on the dashboard and one reminder a week (notification, no trace) until the decision'),
  ('hardening_execution', 'guard:budget_exceeded', 'gate_hardening_blocked', 'Check once per round, before the fan-out (E2, decision 12); overrun bounded by (tasks of the round) × cap per task'),
  ('hardening_execution', 'guard:escalation', 'gate_hardening_blocked', 'Check of the counters on entering the round, like the budget: stagnation (cascade rule + file / category + file / previous_id, patience, pipeline/CI/scope included — D20), rounds cap or duration reached before running a single agent again (D15)'),
  ('hardening_execution', 'task:done', 'hardening_integration', 'All the tasks of the round finished (explicit fan-in, E4)'),
  ('hardening_execution', 'task:failed', 'hardening_evaluation', 'A code task failed or blocked (blocked = failed, reason shown to the admin, decision 7): round non-compliant (fail-closed), unknown cost = the task''s cap'),
  ('hardening_integration', 'task:done', 'hardening_review', 'Iteration branch integrated (conflicts resolved by the integration task if needed)'),
  ('hardening_integration', 'task:failed', 'hardening_evaluation', 'Integration impossible: round non-compliant'),
  ('hardening_review', 'task:done', 'hardening_evaluation', 'Reports of both reviewers and of the tests received'),
  ('hardening_review', 'task:failed', 'hardening_evaluation', 'Failed review or report invalid against the schema: non-compliant, counts as an iteration (v1 fail-open deviation)'),
  ('hardening_evaluation', 'guard:compliant', 'merge', 'No deviation, all reviews valid: merge'),
  ('hardening_evaluation', 'guard:non_compliant', 'hardening_execution', 'Deviations routed to the owner roles (file → folder → role), reports of the previous round passed on (E8)'),
  ('hardening_evaluation', 'guard:escalation', 'gate_hardening_blocked', 'Non-compliant and stagnation (D20: rule + file or category + file or previous_id for 3 consecutive rounds, no new minimum of deviations for 3 evaluations, or a role''s Git tree back to an earlier state; a red CI/pipeline check counts as a deviation rule = <pipeline>:<check>, Opengrep by matchBasedId, unchanged code as a deviation code:unchanged:<role>), cap, duration or budget: escalation in that order'),
  ('gate_hardening_blocked', 'gate:approved', 'hardening_execution', 'Continue: counters at zero (never the cost), top-up = approved + amount; without a top-up when the budget is what blocks, the gate triggers again'),
  ('gate_hardening_blocked', 'gate:correction', 'hardening_execution', 'The admin''s text becomes the instruction of the next round'),
  ('gate_hardening_blocked', 'gate:refused', 'end_refusal', 'Refusal: end of the cycle, requester notified, cleanup'),
  ('gate_hardening_blocked', 'timeout_exceeded', 'gate_hardening_blocked', 'Reminder to the admin (24/48/72 h); beyond: "waiting > 72 h" on the dashboard and one reminder a week (notification, no trace) until the decision'),
  ('gate_hardening_blocked', 'gate:scope_change', 'contract', '"Scope change" button: a defect of the frozen contract (found by a red CI) goes back to the contract with the admin''s text, like Gate 1'),
  ('merge', 'task:done', 'waiting_ci', 'Squash into main; the CI starts'),
  ('merge', 'guard:diff_out_of_scope', 'hardening_execution', 'Out-of-scope diff (file outside the role, rules or CI touched): not a technical block — round deviation rule = scope:<file> passed on to the roles concerned, counters kept; stagnation / budget / cap / duration escalate if it loops (arbitration A, like the red pipeline)'),
  ('merge', 'task:failed', 'gate_delivery_blocked', 'Real technical failure of the merge (Git error, forge unavailable): the admin decides (decision 5)'),
  ('waiting_ci', 'event:ci_finished:green', 'candidate_image', 'Image built once, digest published'),
  ('waiting_ci', 'event:ci_finished:red', 'hardening_execution', 'Red CI: automatic return to hardening with the failed checks (pipeline_results), counters kept'),
  ('waiting_ci', 'timeout_exceeded', 'gate_delivery_blocked', 'CI silent for 60 min: the admin decides (decision 14)'),
  ('candidate_image', 'guard:gate1_required', 'gate_1', 'First delivery of the tool: Gate 1 (name, domain)'),
  ('candidate_image', 'guard:gate1_already_granted', 'preview_deployment', 'Gate 1 already granted (approvals) or evolution cycle: skipped unconditionally (D5)'),
  ('gate_1', 'gate:approved', 'preview_deployment', 'Name and domain approved, once for the whole life of the tool'),
  ('gate_1', 'gate:correction', 'hardening_execution', '"Correction" button (contract unchanged): instruction passed to hardening, never to scoping (decision 2)'),
  ('gate_1', 'gate:refused', 'end_refusal', 'Refusal: end of the cycle, requester notified, cleanup'),
  ('gate_1', 'timeout_exceeded', 'gate_1', 'Reminder to the admin (24/48/72 h); beyond: "waiting > 72 h" on the dashboard and one reminder a week (notification, no trace) until the decision'),
  ('gate_1', 'gate:scope_change', 'contract', '"Scope change" button: the contract is reviewed with the admin''s text (decision 2)'),
  ('preview_deployment', 'task:done', 'preview_pipeline', 'Preview deployed by digest, health OK: pipeline 2 against that digest before the requester is told (decision 11)'),
  ('preview_deployment', 'task:failed', 'gate_delivery_blocked', 'Failed Preview deployment: the admin decides (decision 5)'),
  ('preview_pipeline', 'event:preview_pipeline_finished:green', 'waiting_preview_feedback', 'All checks green, recorded against the digest: Preview link sent to the requester; the results are shown at Gate 2 (decision 11)'),
  ('preview_pipeline', 'event:preview_pipeline_finished:red', 'hardening_execution', 'At least one red check: automatic return to hardening with the failed checks (pipeline_results), without disturbing the requester, counters kept; the hardening guard-rails escalate if it loops (decision 11)'),
  ('preview_pipeline', 'timeout_exceeded', 'gate_delivery_blocked', 'Pipeline silent for 60 min: the admin decides (decision 14)'),
  ('waiting_preview_feedback', 'event:preview_feedback:satisfied', 'gate_2', 'Preview validated by the requester on an already checked digest: Gate 2, without running the pipeline again'),
  ('waiting_preview_feedback', 'event:preview_feedback:bug', 'hardening_execution', 'The requester''s "bug" button, contract unchanged: hardening, never scoping (D6, decision 8); the new digest goes through the pipeline again before new feedback'),
  ('waiting_preview_feedback', 'event:preview_feedback:new_capability', 'contract', 'The requester''s "new capability" button: the contract is reviewed (D6, decision 8)'),
  ('waiting_preview_feedback', 'timeout_exceeded', 'waiting_preview_feedback', 'Reminder to the requester ×3, then "waiting > 72 h" on the dashboard (after the merge: no pause, no abandonment by the requester — the admin cancels, decision 9)'),
  ('gate_2', 'gate:approved', 'prod_deployment', 'Precise digest approved: promotion'),
  ('gate_2', 'gate:correction', 'hardening_execution', 'Correction requested: instruction passed to hardening'),
  ('gate_2', 'gate:refused', 'end_refusal', 'Refusal: end of the cycle, requester notified, cleanup'),
  ('gate_2', 'timeout_exceeded', 'gate_2', 'Reminder to the admin (24/48/72 h); beyond: "waiting > 72 h" on the dashboard and one reminder a week (notification, no trace) until the decision'),
  ('prod_deployment', 'task:done', 'end_success', 'Same digest in Prod, health OK, deployments row (prod) written — no releases table (decision 16), registry up to date'),
  ('prod_deployment', 'task:failed', 'gate_prod_blocked', 'Failed Prod deployment: dedicated gate, the last healthy prod deployment stays the reference (decision 5, D19)'),
  ('gate_delivery_blocked', 'gate:approved', 'merge', 'Retry: start again from the merge (idempotent), which runs CI → Preview → … again without any agent task (decision 5)'),
  ('gate_delivery_blocked', 'gate:correction', 'hardening_execution', 'Correction requested: instruction passed to hardening'),
  ('gate_delivery_blocked', 'gate:refused', 'end_refusal', 'Refusal: end of the cycle, requester notified, cleanup'),
  ('gate_delivery_blocked', 'timeout_exceeded', 'gate_delivery_blocked', 'Reminder to the admin (24/48/72 h); beyond: "waiting > 72 h" on the dashboard and one reminder a week (notification, no trace) until the decision'),
  ('gate_prod_blocked', 'gate:approved', 'prod_deployment', 'Retry: runs again only the Prod deployment of the same digest approved at Gate 2, without redoing merge, CI, Preview or Gate 2 (D19)'),
  ('gate_prod_blocked', 'gate:correction', 'hardening_execution', 'Correction requested: instruction passed to hardening'),
  ('gate_prod_blocked', 'gate:refused', 'end_refusal', 'Refusal: end of the cycle, requester notified, cleanup'),
  ('gate_prod_blocked', 'timeout_exceeded', 'gate_prod_blocked', 'Reminder to the admin (24/48/72 h); beyond: "waiting > 72 h" on the dashboard and one reminder a week (notification, no trace) until the decision'),
